const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taiwan = ee.Geometry.Rectangle([119.5, 21.5, 122.5, 25.5]); // Bounding box for Taiwan

  // Period 1: April 20 - May 12, 2020
  const startDate1 = '2020-04-20';
  const endDate1 = '2020-05-12';

  // Period 2: February 10 - February 25, 2020
  const startDate2 = '2020-02-10';
  const endDate2 = '2020-02-25';

  const bandName = 'NO2_column_number_density';
  const qaBand = 'tropospheric_NO2_column_number_density_qa_value';
  const scale = 5000; // Resolution of Sentinel-5P is ~5.5km, using 5km scale

  // Function to get and process NO2 collection
  function getNO2Collection(startDate, endDate, geometry) {
    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .select([bandName, qaBand]);

    // Apply quality filter: QA value > 0.75 for good quality data
    collection = collection.filter(ee.Filter.gt(qaBand, 0.75));

    return collection;
  }

  // 2. Data Acquisition & Check for Period 1
  const collection1 = getNO2Collection(startDate1, endDate1, taiwan);
  const size1 = await collection1.size().getInfo();
  if (size1 === 0) {
    console.log(`Period 1 (${startDate1} to ${endDate1}) NO2 images: 0`);
    console.log("C1: Empty Collection (No images found for Period 1).");
    return;
  }
  console.log(`Period 1 (${startDate1} to ${endDate1}) NO2 images: ${size1}`);

  // 2. Data Acquisition & Check for Period 2
  const collection2 = getNO2Collection(startDate2, endDate2, taiwan);
  const size2 = await collection2.size().getInfo();
  if (size2 === 0) {
    console.log(`Period 2 (${startDate2} to ${endDate2}) NO2 images: 0`);
    console.log("C1: Empty Collection (No images found for Period 2).");
    return;
  }
  console.log(`Period 2 (${startDate2} to ${endDate2}) NO2 images: ${size2}`);

  // 3. Processing and Calculation for Period 1
  const meanImage1 = collection1.mean().select(bandName);
  const stats1 = await meanImage1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 4
  }).getInfo();

  const meanNO2_1 = stats1[bandName + '_mean'];
  const pixelCount1 = stats1[bandName + '_count'];

  if (pixelCount1 === 0) {
    console.log("C2: No Valid Pixels (Period 1: 0 pixels remain after masking/processing).");
    return;
  }
  if (meanNO2_1 === null || isNaN(meanNO2_1)) {
    console.log("C3: Calculation Failure (Period 1 NO2 mean is invalid).");
    return;
  }
  console.log(`Period 1 Mean NO2: ${meanNO2_1.toExponential(2)} mol/m^2 (Pixels: ${pixelCount1})`);

  // 3. Processing and Calculation for Period 2
  const meanImage2 = collection2.mean().select(bandName);
  const stats2 = await meanImage2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 4
  }).getInfo();

  const meanNO2_2 = stats2[bandName + '_mean'];
  const pixelCount2 = stats2[bandName + '_count'];

  if (pixelCount2 === 0) {
    console.log("C2: No Valid Pixels (Period 2: 0 pixels remain after masking/processing).");
    return;
  }
  if (meanNO2_2 === null || isNaN(meanNO2_2)) {
    console.log("C3: Calculation Failure (Period 2 NO2 mean is invalid).");
    return;
  }
  console.log(`Period 2 Mean NO2: ${meanNO2_2.toExponential(2)} mol/m^2 (Pixels: ${pixelCount2})`);

  // 4. Comparison and Final Answer
  const percentageChange = ((meanNO2_1 - meanNO2_2) / meanNO2_2) * 100;
  console.log(`Percentage Change: ${percentageChange.toFixed(2)}%`);

  if (meanNO2_1 > meanNO2_2) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
